package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.database.sqlite.*;

/** Rebuildable FTS index. Document text is stored once and is never sent to a server. */
final class LibrarySearchStore extends SQLiteOpenHelper {
    final Context c;
    LibrarySearchStore(Context c){super(c,"seeky-library-search.db",null,1);this.c=c.getApplicationContext();setWriteAheadLoggingEnabled(true);}
    public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE scope(id INTEGER PRIMARY KEY,value TEXT NOT NULL)");d.execSQL("CREATE TABLE documents(material INTEGER PRIMARY KEY,hash TEXT NOT NULL,parts INTEGER NOT NULL,next_part INTEGER NOT NULL DEFAULT 0,done INTEGER NOT NULL DEFAULT 0,partial INTEGER NOT NULL DEFAULT 0)");d.execSQL("CREATE TABLE segments(id INTEGER PRIMARY KEY,material INTEGER NOT NULL,part INTEGER NOT NULL,start INTEGER NOT NULL,body TEXT NOT NULL,digest TEXT NOT NULL,UNIQUE(material,part,start))");d.execSQL("CREATE INDEX segment_origin ON segments(material,part)");d.execSQL("CREATE VIRTUAL TABLE texts USING fts4(body,content='segments',tokenize=unicode61)");d.execSQL("CREATE TRIGGER segment_insert AFTER INSERT ON segments BEGIN INSERT INTO texts(docid,body) VALUES(new.id,new.body); END");d.execSQL("CREATE TRIGGER segment_before_delete BEFORE DELETE ON segments BEGIN DELETE FROM texts WHERE docid=old.id; END");}
    public void onUpgrade(SQLiteDatabase d,int old,int version){}
    void scope(){SQLiteDatabase d=getWritableDatabase();String current=TaskStore.workspace(c),old=null;try(Cursor r=d.rawQuery("SELECT value FROM scope WHERE id=1",null)){if(r.moveToFirst())old=r.getString(0);}if(!current.equals(old)){clear();d.execSQL("INSERT OR REPLACE INTO scope(id,value) VALUES(1,?)",new Object[]{current});}}
    void clear(){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{d.delete("segments",null,null);d.delete("documents",null,null);d.setTransactionSuccessful();}finally{d.endTransaction();}}
    StudyStore.Row document(long material){try(Cursor c=getReadableDatabase().query("documents",null,"material=?",new String[]{""+material},null,null,null)){return c.moveToFirst()?TaskStore.row(c):null;}}
    void start(long material,String hash,int parts){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{d.delete("segments","material=?",new String[]{""+material});d.insertWithOnConflict("documents",null,StudyStore.values("material",material,"hash",hash,"parts",parts,"next_part",0,"done",0),SQLiteDatabase.CONFLICT_REPLACE);d.setTransactionSuccessful();}finally{d.endTransaction();}}
    void part(long material,int part,String text,boolean partial){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{d.delete("segments","material=? AND part=?",new String[]{""+material,""+part});String digest=ReaderStore.digest(text);for(int at=0;at<text.length();){int end=Math.min(text.length(),at+12000);if(end<text.length()&&Character.isLowSurrogate(text.charAt(end)))end--;d.insertOrThrow("segments",null,StudyStore.values("material",material,"part",part,"start",at,"body",text.substring(at,end),"digest",digest));at=end;}d.execSQL("UPDATE documents SET next_part=?,partial=MAX(partial,?) WHERE material=?",new Object[]{part+1,partial?1:0,material});d.setTransactionSuccessful();}finally{d.endTransaction();}}
    static String match(String query){String[] words=query.trim().split("\\s+");StringBuilder out=new StringBuilder();for(String word:words){word=word.replace("\"","").replace("*","").trim();if(word.isEmpty())continue;if(out.length()>0)out.append(" ");out.append('"').append(word).append('"');if(out.length()>500)break;}return out.toString();}
}
